// Kenya legal-matter classifier (inline copy of legal-bot/kenya-jurisdiction-classifier.js).
// Keep this in sync with that file if the rules change.

const COURT_MONEY_LIMITS = {
  smallClaimsCourtMax: 1000000,
  residentMagistrateMax: 5000000,
  seniorResidentMagistrateMax: 7000000,
  principalMagistrateMax: 10000000,
  seniorPrincipalMagistrateMax: 15000000,
  chiefMagistrateMax: 20000000
};

const CASE_RULES = [
  { category: 'Employment / Labour Dispute', keywords: ['fired','dismissed','dismissal','termination','terminated','salary','wages','unpaid pay','workplace','employer','employee','redundan','wrongful dismissal','nssf','nhif','leave pay','contract of employment'], court: 'Employment and Labour Relations Court (ELRC)', basis: "Employment and Labour Relations Court Act, 2011 (s.12) — the ELRC has exclusive original jurisdiction over employment and labour relations disputes." },
  { category: 'Land / Environment Dispute', keywords: ['land','boundary','title deed','eviction','trespass','environment','pollution','lease','plot','survey','land dispute','landlord'], court: 'Environment and Land Court (ELC)', basis: "Environment and Land Court Act, 2011 (s.13) — the ELC has exclusive original jurisdiction over land use, title, tenure, boundaries and environmental disputes." },
  { category: 'Muslim Personal Law', keywords: ['kadhi','islamic marriage','muslim marriage','muslim divorce','islamic inheritance','islamic succession'], court: "Kadhi's Court", basis: "Constitution Art. 170 & Kadhis' Courts Act (Cap. 11) — jurisdiction limited to Muslim personal status, marriage, divorce or inheritance where all parties profess Islam and submit to the court." },
  { category: 'Family / Succession', keywords: ['divorce','custody','maintenance','succession','inheritance','probate','letters of administration','estate','marriage','adoption'], court: null, basis: 'Magistrates\' Courts Act, 2015 (family matters) and the Law of Succession Act (Cap. 160).' },
  { category: 'Criminal Matter', keywords: ['arrested','police','charged','criminal case','theft','stolen','assault','robbery','murder','bail','bond','cybercrime'], court: null, basis: 'Criminal Procedure Code (Cap. 75) — most matters tried in the Magistrate\'s Court; capital/grave offences in the High Court.' },
  { category: 'Constitutional / Judicial Review / Human Rights', keywords: ['constitutional','judicial review','human rights violation','fundamental rights','habeas corpus','unconstitutional','petition against the state'], court: 'High Court', basis: 'Constitution Art. 165(3) — the High Court has original jurisdiction to interpret the Constitution and enforce the Bill of Rights.' },
  { category: 'General Civil / Contract / Debt Claim', keywords: ['contract','debt','breach','sue','owe me','owes me','unpaid invoice','goods','services','loan','refund','rent arrears','compensation'], court: null, basis: "Magistrates' Courts Act, 2015 and Small Claims Court Act, 2016 — routed by claim value." }
];

function resolveCivilCourt(amount) {
  if (amount == null) return { court: "Small Claims Court or Magistrate's Court (class depends on claim value — amount not provided)", note: 'Provide the claim amount to pin down the exact court class.' };
  const L = COURT_MONEY_LIMITS;
  if (amount <= L.smallClaimsCourtMax) return { court: 'Small Claims Court', note: `Claims up to KES ${L.smallClaimsCourtMax.toLocaleString()} — no advocate required to file, resolution targeted within 60 days.` };
  if (amount <= L.residentMagistrateMax) return { court: "Resident Magistrate's Court", note: `Civil claims up to KES ${L.residentMagistrateMax.toLocaleString()}.` };
  if (amount <= L.seniorResidentMagistrateMax) return { court: "Senior Resident Magistrate's Court", note: `Civil claims up to KES ${L.seniorResidentMagistrateMax.toLocaleString()}.` };
  if (amount <= L.principalMagistrateMax) return { court: "Principal Magistrate's Court", note: `Civil claims up to KES ${L.principalMagistrateMax.toLocaleString()}.` };
  if (amount <= L.seniorPrincipalMagistrateMax) return { court: "Senior Principal Magistrate's Court", note: `Civil claims up to KES ${L.seniorPrincipalMagistrateMax.toLocaleString()}.` };
  if (amount <= L.chiefMagistrateMax) return { court: "Chief Magistrate's Court", note: `Civil claims up to KES ${L.chiefMagistrateMax.toLocaleString()}.` };
  return { court: 'High Court', note: `High Court has unlimited pecuniary jurisdiction — applies above the Chief Magistrate's ceiling of KES ${L.chiefMagistrateMax.toLocaleString()}.` };
}

function resolveFamilyCourt(text, amount) {
  if (/succession|probate|letters of administration|estate|inheritance/.test(text)) {
    const civil = resolveCivilCourt(amount);
    return { court: civil.court === 'High Court' ? 'High Court (Family Division)' : `${civil.court} (Succession Cause)`, note: 'Succession/probate follows the same value-based ladder as ordinary civil claims, using the estate value.' };
  }
  return { court: "Magistrate's Court (Family Division)", note: "Divorce, custody and maintenance are normally filed at the Magistrate's Court; parties who profess Islam and submit to it may instead use the Kadhi's Court." };
}

function resolveCriminalCourt(text) {
  const graveOffence = /murder|treason|robbery with violence|manslaughter|terrorism/.test(text);
  return graveOffence
    ? { court: 'High Court', note: 'Capital/grave offences are tried in the High Court.' }
    : { court: "Magistrate's Court", note: "Most criminal matters, including most bail/bond applications, start in the Magistrate's Court." };
}

const ADVOCATES_ACT_TRIGGERS = [
  { test: /\b(qualified|licensed|licence|license|practicing certificate|practising certificate|real lawyer|verify.*advocate)\b/i, note: "Advocates Act (Cap. 16), ss. 9–17: only a person admitted as an advocate by the Chief Justice, enrolled on the Roll of Advocates and holding a current Practising Certificate may lawfully practise law in Kenya. Verify standing with the Law Society of Kenya (LSK)." },
  { test: /\b(fee|fees|cost|charge|how much.*lawyer|legal fees)\b/i, note: "Advocates Act (Cap. 16), s.44 & the Advocates (Remuneration) Order: advocates' fees are governed by the Remuneration Order and can be challenged through taxation of a bill of costs." },
  { test: /\b(complain|complaint|misconduct|unethical|scammed by.*lawyer|sue my lawyer)\b/i, note: 'Advocates Act (Cap. 16), Part IX: complaints against an advocate go to the Advocates Complaints Commission or the LSK Disciplinary Committee; serious cases go to the Advocates Disciplinary Tribunal.' },
  { test: /\bunqualified person|non-advocate|not a lawyer.*representing\b/i, note: "Advocates Act (Cap. 16), s.34: it is an offence for an unqualified person to act as, or pretend to be, an advocate, or to prepare legal documents for a fee without being one." }
];

function classify(rawText, claimAmount) {
  const text = (rawText || '').toLowerCase();
  const amount = claimAmount == null || claimAmount === '' ? null : Number(claimAmount);

  let match = null;
  for (const rule of CASE_RULES) {
    if (rule.keywords.some((kw) => text.includes(kw))) { match = rule; break; }
  }

  let court, basis, note = null;
  if (!match) {
    court = 'Unclear — needs human triage';
    basis = 'No case-type keywords matched. An advocate should review the raw inquiry before routing.';
  } else if (match.category === 'General Civil / Contract / Debt Claim') {
    const resolved = resolveCivilCourt(amount);
    court = resolved.court; note = resolved.note; basis = match.basis;
  } else if (match.category === 'Family / Succession') {
    const resolved = resolveFamilyCourt(text, amount);
    court = resolved.court; note = resolved.note; basis = match.basis;
  } else if (match.category === 'Criminal Matter') {
    const resolved = resolveCriminalCourt(text);
    court = resolved.court; note = resolved.note; basis = match.basis;
  } else {
    court = match.court; basis = match.basis;
  }

  const advocatesActNotes = ADVOCATES_ACT_TRIGGERS.filter((t) => t.test.test(text)).map((t) => t.note);

  return {
    caseCategory: match ? match.category : 'Unclassified',
    recommendedCourt: court,
    jurisdictionBasis: basis,
    courtNote: note,
    advocatesActNotes,
    disclaimer: 'Automated triage only — not legal advice. Confirm with a qualified advocate before filing.'
  };
}

const source = $input.first().json;
const message = (source.message || source.text || source.Body || source.inquiry || '').toString();
const amount = source.amount || source.claimAmount || source.value || null;
const name = (source.name || source.Name || source.ProfileName || 'Unknown').toString().trim();
const phone = (source.phone || source.Phone || source.waId || source.WaId || source.From || '').toString().trim();

const result = classify(message, amount);

return [{
  json: {
    timestamp: new Date().toISOString(),
    name,
    phone,
    inquiry: message.trim(),
    claimAmount: amount,
    ...result
  }
}];

const r = $input.first().json;

let lines = [];
lines.push(`Thanks${r.name && r.name !== 'Unknown' ? ' ' + r.name : ''}, here's an initial read on your matter:`);
lines.push(`\nCase type: ${r.caseCategory}`);
lines.push(`Likely court: ${r.recommendedCourt}`);
lines.push(`Why: ${r.jurisdictionBasis}`);
if (r.courtNote) lines.push(r.courtNote);
if (r.advocatesActNotes && r.advocatesActNotes.length) {
  lines.push('\nAdvocates Act notes:');
  r.advocatesActNotes.forEach((n) => lines.push(`- ${n}`));
}
lines.push(`\n${r.disclaimer}`);
lines.push('An advocate from our team will follow up to confirm next steps.');

return [{ json: { ...r, replyMessage: lines.join('\n') } }];
